INSERT INTO `paquete` (`id`, `nombre`, `estado`, `descripcion`, `detalle`, `imagen`, `ciudad_id`, `descuento`) VALUES (1,'Descubre Buenos Aires Clásico',1,'5 días por lo mejor de la capital argentina','Incluye city tours y gastronomía local','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770310218/1_ylaoz1.jpg',1,NULL),(2,'Escapada Cultural en BA',1,'Circuito cultural con museos y barrios históricos','Guía bilingüe, entradas incluidas','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307018/2_d7uvsr.jpg',1,NULL),(3,'BA y Vinos Argentinos',1,'Experiencia combinada con viñedos cercanos','Catas y transporte incluidos','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307025/3_ouffpg.webp',1,NULL),(4,'Aventura en Sierras de Córdoba',1,'Naturaleza y trekking en sierras','Incluye alojamiento y guía','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307032/4_mccyty.jpg',2,NULL),(5,'Córdoba Gastronómica',1,'Experiencia culinaria cordobesa','Visitas a bodegas y feria artesanal','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307047/5_aya0dl.jpg',2,0.50),(6,'City & Cultura Córdoba',1,'Circuito urbano con historia y arte','Entradas y guía profesional','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770310232/6_ebp1mu.jpg',2,NULL),(7,'Rosario Escénica',1,'Descubre el río Paraná y parques centrales','Incluye paseo en barco y bike tour','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307071/7_jfs8nl.jpg',3,NULL),(8,'Rosario Histórico',1,'Circuito por historia y cultura local','Visitas guiadas y entradas','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307080/8_z6po0c.jpg',3,NULL),(9,'Gastronomía en Rosario',1,'Tour culinario por los sabores locales','Degustación incluida','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307090/9_trthw8.jpg',3,NULL),(10,'Montevideo Esencial',1,'6 días recorriendo la capital uruguaya','City tours y gastronomía típica','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307099/10_nlbqfl.jpg',4,NULL),(11,'Relax y Cultura en Montevideo',1,'Circuito histórico + relax frente al Río de la Plata','Entradas y traslados','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307108/11_dyrfbs.jpg',4,NULL),(12,'Gastronomía Uruguaya',1,'Sabores auténticos del Uruguay','Tours de comida típica incluidos','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770310251/12_w0i1ee.jpg',4,NULL),(13,'Lo Mejor de Santiago',1,'5 días entre cultura y naturaleza urbana','Incluye tours y ascenso al cerro','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307135/13_v6dpil.jpg',5,NULL),(14,'Santiago Gourmet',1,'Tour de sabores chilenos','Degustaciones en mercados y viñedos','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307149/14_rcilsv.jpg',5,NULL),(15,'Santiago Cultural',1,'Visita a barrios históricos y museos','Entradas y guía incluidos','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307162/15_jyjklk.jpg',5,NULL),(16,'Lima Clásica',1,'4 días recorriendo lo mejor de Lima','City tours y experiencias locales','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307180/16_hbssiw.jpg',6,NULL),(17,'Lima Gastronómica',1,'Delicias peruanas y mercados típicos','Incluye degustaciones','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307192/17_xdt8z8.jpg',6,NULL),(18,'Lima y Ruinas Cercanas',1,'Experiencia urbana + arqueológica','Visitas a sitios históricos','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307202/18_tdzqou.jpg',6,NULL),(19,'Bogotá Esencial',1,'4 días entre cultura y naturaleza urbana','Tours por museos y cerros','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307209/19_ti07ew.jpg',7,NULL),(20,'Bogotá Sabor Local',1,'Experiencias culinarias latinoamericanas','Degustaciones y mercado típico','https://res.cloudinary.com/dy8lzfj2h/image/upload/v1770307219/20_hite75.jpg',7,NULL),(21,'Bogotá Cultural',1,'Museos y patrimonio histórico','Guía profesional y entradas','https://res.cloudinary.com/dy8lzfj2h/image/upload/v17703